// 공통 API를 받아 미션 시작과 1게임초 사건을 기록한다.
export default function registerMod(netstorm) {
    // 현재 사건의 읽기 전용 상태를 로그에 기록한다.
    netstorm.on('sessionStart', () => netstorm.log('info', JSON.stringify(netstorm.getState())));
    // 게임 시계와 분리된 모드 전용 결정론 난수를 기록한다.
    netstorm.on('tick', (event) => netstorm.log('info', JSON.stringify({ second: event.gameSeconds, sample: netstorm.randomInt(100) })));
}
